  "settings.compressionInfo": "restic इस रिपॉज़िटरी में नया डेटा कैसे पैक करे। स्वचालित restic का डिफ़ॉल्ट है और ज़्यादातर डेटा के लिए ठीक है। अधिकतम ज़्यादा जगह बचाता है और बैकअप व कॉपी में ज़्यादा CPU समय लेता है। बंद डेटा को बिना संपीड़न के रखता है, जो पहले से संपीड़ित डेटा जैसे वीडियो या फ़ोटो में मदद करता है। पुराने फ़ॉर्मैट संस्करण 1 वाली रिपॉज़िटरी संपीड़न नहीं कर सकती और इस सेटिंग को अनदेखा करती है।",
