  "offsite.wizard.passwordWarning": "यह पासवर्ड केवल एक बार दिखाया जाता है और BombVault इसे कभी सहेजता नहीं है। इसे अभी सहेज लें। नीचे दिए गए क्रेडेंशियल्स के लिए यह ज़रूरी है और इसे वापस नहीं पाया जा सकता।",
  "offsite.wizard.tlsNote": "यह तरीका सामान्य HTTP इस्तेमाल करता है। भरोसेमंद LAN या VPN पर ठीक है। अगर स्टोरेज बॉक्स इंटरनेट से पहुँच योग्य है, तो rest-server को HTTPS (एक TLS रिवर्स प्रॉक्सी) के पीछे रखें ताकि रिपॉज़िटरी क्रेडेंशियल साफ़ टेक्स्ट में न भेजा जाए।",
