  "offsite.wizard.passwordInfo": "एक ही रहस्य, दो रूपों में। ऊपर का सादा पाठ इस गंतव्य के REST पासवर्ड में जाता है, इसी मशीन पर। नीचे की विधियाँ वही पासवर्ड पहले से हैश किए हुए रूप में रखती हैं, उस पंक्ति में जो .htpasswd में जोड़ती है, और वह पंक्ति भंडारण मशीन पर जाती है। आपको खुद कुछ हैश नहीं करना है।",
  "offsite.wizard.repoUrlInfo": "पथ का पहला हिस्सा उपयोगकर्ता है, फ़ोल्डर नहीं: rest:http://box:8000/उपयोगकर्ता/भंडार। बनाया गया सर्वर हर उपयोगकर्ता को केवल उसका अपना पथ देता है, इसलिए उपयोगकर्ता छोड़ने पर सही पासवर्ड के साथ भी 401 मिलता है।",
