  "offsite.rcloneWarning": "rclone serve restic --append-only में एक खुली अपस्ट्रीम रीट्राई बग है जो अपेंड को खो सकती है। अपरिवर्तनीय ऑफ़-साइट के लिए rest-server की सिफ़ारिश की जाती है।",
  "offsite.s3Unverified": "ध्यान दें: S3 अपेंड-ओनली को स्वचालित रूप से सत्यापित नहीं किया जा सकता। बकेट वर्ज़निंग + डिलीट-निषेध खुद सेट करें; स्कोरकार्ड इस डोमेन को अभी भी असत्यापित के रूप में चिह्नित रखता है।",
