  "offsite.prune.title": "5 · ऑफ़-साइट प्रूनिंग",
  "offsite.prune.info": "यह चरण सिर्फ़ बताता है कि क्या होता है, यह कुछ भी सेट नहीं करता। यह कॉपी प्रून होगी या नहीं, यह चरण 4 के अपेंड-ओनली और सेटिंग्स, ऑफ़-साइट रिटेंशन में दिए रखने वाले मानों से तय होता है। किसी अपेंड-ओनली कॉपी को फिर भी प्रून करना हो, तो स्टोरेज की ओर restic forget --prune चलाएँ, या तो उसके अपने शेड्यूल पर या थोड़ी देर के लिए दूसरा, बिना अपेंड-ओनली वाला REST सर्वर खड़ा करके, उसी से प्रून करके और फिर उसे बंद करके।",
  "offsite.prune.stateFarSide": "यहाँ से कुछ भी इस कॉपी को प्रून नहीं करता। अपेंड-ओनली चालू है, इसलिए BombVault इसमें सिर्फ़ जोड़ता है, और प्रून करना स्टोरेज पक्ष का काम है।",
  "offsite.prune.statePolicy": "BombVault हर प्रतिकृति के बाद ऑफ़-साइट रिटेंशन नीति के अनुसार इस कॉपी को प्रून करता है।",
  "offsite.prune.stateNone": "कुछ भी इस कॉपी को प्रून नहीं करता। अपेंड-ओनली बंद है और हर ऑफ़-साइट रखने वाला मान 0 है, इसलिए यह तब तक बढ़ती रहेगी जब तक डिस्क साथ देती है।",
  "offsite.prune.effective": "{last} नवीनतम, {daily} दैनिक, {weekly} साप्ताहिक, {monthly} मासिक, {yearly} वार्षिक रखता है।",
  "offsite.prune.editedElsewhere": "सेटिंग्स, ऑफ़-साइट रिटेंशन में सेट किया जाता है। ये मान सभी डोमेन में साझा हैं।",
  "offsite.prune.budgetInfo": "जैसे ही ऑफ़-साइट रिपॉज़िटरी इतने गीगाबाइट से बड़ी होती है, अलार्म बजाता है। यह कभी कुछ नहीं हटाता, इसलिए यह उस कॉपी का सुरक्षा जाल है जिसे कोई प्रून नहीं करता।",
  "settings.retentionImmutableNotPruned": "अपेंड-ओनली ऑफ़-साइट गंतव्य यहाँ से कभी प्रून नहीं होता, चाहे ये मान कुछ भी कहें। ऑफ़-साइट सहायक में उसका अपना चरण बताता है कि उसे स्टोरेज की ओर से कैसे प्रून करें।",

