  "settings.retentionTitle": "स्नैपशॉट रिटेंशन",
  "settings.retentionHint": "प्रति आइटम कितने बैकअप रखे जाएँ। हर बैकअप के बाद, restic इस नीति के अनुसार पुराने स्नैपशॉट प्रून करता है। सभी शून्य = सब कुछ रखें (बंद)।",
  "excludes.advisoryImmichDb": "Immich हर फ़ोटो के एल्बम, चेहरे और तारीखें एक PostgreSQL डेटाबेस में रखता है, जो एक बिलकुल अलग कंटेनर में चलता है, इसलिए यह बैकअप उसे शामिल नहीं करता। यहाँ से रीस्टोर करने पर तस्वीरें लौट आती हैं, पर ये सब नहीं। BombVault उस डेटाबेस कंटेनर का बैकअप लेते समय अपने आप उसका डंप ले लेता है, इसलिए देख लें कि वह आपके शेड्यूल में शामिल है।",
  "excludes.advisoryNextcloudDb": "Nextcloud अपने खाते, शेयर और टैग एक डेटाबेस में रखता है, जो आमतौर पर एक अलग कंटेनर में चलता है, इसलिए यह बैकअप उसे शामिल नहीं करता। फ़ाइलें वापस आ जाती हैं, शेयरिंग नहीं। BombVault उस डेटाबेस कंटेनर का बैकअप लेते समय अपने आप उसका डंप ले लेता है, इसलिए देख लें कि वह आपके शेड्यूल में शामिल है।",
  "excludes.presetLoad": "{app} के लिए सुझाए गए अपवाद लोड करें",
