  "excludes.presetHint.crashReports": "क्रैश रिपोर्ट। रीस्टोर के बाद ऐप को इनकी ज़रूरत नहीं होती।",
  "excludes.presetHint.previews": "बनाए गए पूर्वावलोकन चित्र। रीस्टोर के बाद ऐप इन्हें फिर से बनाता है, बड़ी लाइब्रेरी में इसमें घंटों लग सकते हैं।",
  "excludes.presetHint.trickplay": "सीक बार के लिए चित्र। रीस्टोर के बाद एक निर्धारित कार्य इन्हें फिर से बनाता है।",
  "excludes.presetHint.metadata": "ऐप के डाउनलोड किए पोस्टर और चित्र। मेटाडेटा रीफ़्रेश इन्हें फिर से ले आता है, पर आपके खुद अपलोड किए चित्र भी यहीं हैं और वे खो जाएँगे। यह प्रविष्टि शुरू में बंद रहती है।",
  "excludes.presetHint.covers": "पोस्टर और कवर। अगले रीफ़्रेश पर ऐप इन्हें फिर से डाउनलोड करता है।",
  "excludes.presetHint.encodedVideo": "प्लेबैक के लिए ऐप की एनकोड की गई प्रतियाँ। मूल फ़ाइलें बैकअप में रहती हैं, और रीस्टोर के बाद ऐप इन्हें फिर से एनकोड करता है।",
  "excludes.presetHint.models": "मशीन लर्निंग मॉडल। शुरू होने पर ऐप इन्हें फिर से डाउनलोड करता है।",
  "rcloneRemote.heading": "SMB या WebDAV गंतव्य जोड़ें",
  "rcloneRemote.hint": "Windows या Samba शेयर, या Nextcloud जैसे किसी WebDAV सर्वर तक पहुँचता है, उसे होस्ट पर माउंट किए बिना। restic माउंट किए गए CIFS शेयर पर रिपॉज़िटरी रखने की सलाह नहीं देता, और यह तरीका माउंट से पूरी तरह बचाता है। पासवर्ड rclone को सौंपा जाता है, जो उसे अपने फ़ॉर्मैट में सहेजता है, और वह कभी साफ़ टेक्स्ट में नहीं रखा जाता। NFS यहाँ उपलब्ध नहीं है, क्योंकि न तो restic और न ही rclone इसे सपोर्ट करता है: NFS के लिए, Unraid पर एक्सपोर्ट माउंट करें और उस पर एक बैकअप पथ सेट करें।",
