  "coverage.title": "बैकअप नहीं हुआ",
  "coverage.hint": "इस सर्वर पर वह सब कुछ जिसे कोई स्वचालित बैकअप कवर नहीं करता। ऊपर वाला सुरक्षा कार्ड बताता है कि शेड्यूल किए गए बैकअप समय पर चले या नहीं; यह कार्ड दिखाता है कि क्या शेड्यूल में है ही नहीं, जो कोई और पेज नहीं दिखाता। बैकअप का जो प्रकार आपने बंद किया है, वह यहाँ नहीं गिना जाता। जो ZFS डेटासेट आपने नहीं जोड़े, वे भी यहाँ नहीं गिने जाते; ZFS पेज उन्हें दिखाता है।",
