  // Off-site (rclone)
  "rclone.title": "ऑफ़-साइट (rclone)",
  "rclone.hint": "क्लाउड पर बैकअप लेने के लिए rclone कॉन्फ़िगरेशन पेस्ट करें (Backblaze B2, S3, Google Drive, …)। यह एन्क्रिप्टेड सहेजा जाता है। SMB/NFS को rclone की ज़रूरत नहीं: Unraid पर शेयर माउंट करें और उस पर एक बैकअप पथ सेट करें।",
  "rclone.configured": "कॉन्फ़िगर किए गए रिमोट",
  "rclone.pathHint": "फिर उस डोमेन को ऑफ़-साइट भेजने के लिए बैकअप पथ को \"rclone:<remote>:<bucket>/path\" सेट करें।",
  "cloud.title": "साझा क्लाउड क्रेडेंशियल (S3 / restic REST)",
  "cloud.hint": "rclone के बिना, ऑफ़-साइट restic बैकएंड के लिए क्रेडेंशियल्स। सहेजने के बाद, बैकअप पथ को किसी रिमोट रिपॉज़िटरी पर सेट करें, जैसे s3:s3.amazonaws.com/bucket/path, rest:http://host:8000/repo, b2:bucket:path या sftp:user@host:/repo। गुप्त जानकारी एन्क्रिप्टेड सहेजी जाती है और फिर कभी नहीं दिखाई जाती।",
  "cloud.secretSet": "सहेजा गया, रखने के लिए खाली छोड़ें",
  "cloud.storageClass.label": "ऑफ़-साइट स्टोरेज क्लास",
  "cloud.storageClass.default": "(प्रोवाइडर का डिफ़ॉल्ट)",
  "cloud.storageClass.hint": "यह केवल नेटिव S3 बैकएंड (s3: से शुरू होने वाली रिपॉज़िटरीज़) पर लागू होता है। डीप-आर्काइव टियर (Glacier Flexible Retrieval, Deep Archive) जानबूझकर नहीं दिए जाते क्योंकि वे restic रीस्टोर को तोड़ देते हैं।",
