  "notify.scheduledSummary": "शेड्यूल किए गए रन का सारांश दें",
  "notify.scheduledSummaryHint": "हर कंटेनर/VM के लिए अलग मैसेज के बजाय, हर शेड्यूल किए गए बैकअप रन के लिए एक ही सारांश भेजें (जैसे \"42 में से 45 सफल\")। Healthchecks पहले से ही सारांशित होता है। मैनुअल बैकअप अब भी प्रति-आइटम सूचित करते हैं।",
  "notify.notifyOnUpdate": "कंटेनर अपडेट पर सूचित करें",
  "notify.notifyOnUpdateHint": "जब \"बैकअप के बाद अपडेट\" किसी कंटेनर को नई इमेज में अपग्रेड करता है, तो एक मैसेज भेजें ताकि आप जाँच सकें कि यह अभी भी काम करता है। यह हर अपडेट किए गए कंटेनर के लिए चलता है (अपडेट दुर्लभ होते हैं)।",
  "notify.unraid": "Unraid सूचनाएँ",
  "notify.unraidHint": "Unraid के अपने सूचना सिस्टम को भेजें (जो Pushover, ईमेल, Discord, … को आगे भेज सकता है)। यह Settings → VM Backup over SSH के SSH कनेक्शन पर चलता है, इसलिए वहाँ कुंजी अधिकृत होनी चाहिए, लेकिन libvirt/VM ज़रूरी नहीं हैं (अगर आप VM का बैकअप नहीं लेते तो \"libvirt not reachable\" परिणाम को नज़रअंदाज़ करें)। जाँचने के लिए नीचे दिए Send test का उपयोग करें।",
  "notify.unraidPlatformMismatch": "BombVault ने इस होस्ट को \"{platform}\" के रूप में पहचाना है, Unraid के रूप में नहीं। यह स्विच चालू होने पर भी Unraid सूचनाएँ बंद रहती हैं। अगर यह वाकई एक Unraid होस्ट है, तो जाँचें कि होस्ट का /boot कंटेनर के अंदर /host/boot से बाइंड-माउंट है (BombVault Unraid टेम्पलेट देखें) और कंटेनर को फिर से शुरू करें।",
