  "dbdump.damagedBadge": "क्षतिग्रस्त",
  "dbdump.damagedHint": "यह डंप अपनी जाँचों में विफल रहा और स्वतः हटाया नहीं जा सका। इसे न डाउनलोड किया जा सकता है, न आयात। इसे मिटा दें।",
