  "dbdump.saveHint": "डंप को सर्वर पर चुने हुए फ़ोल्डर में फ़ाइल के रूप में लिखता है, स्वामी nobody:users, ताकि आप उसे नेटवर्क शेयर से खोल सकें। फ़ाइल में हर तालिका और डेटाबेस उपयोगकर्ताओं के पासवर्ड हैश होते हैं; इसे वहीं रखें जहाँ केवल आप पहुँचें।",
  "dbdump.saveCancelHint": "रद्द करने पर सहेजना रुक जाता है और अधूरी फ़ाइल हटा दी जाती है।",
  "dbdump.savedTo": "{path} में सहेजा गया",
  "dbdump.import": "नए डेटाबेस में आयात करें",
  "dbdump.importConfirm": "यह {engine} {version} डंप {container} में आयात करें? BombVault कंटेनर रोकता है, उसका डेटा फ़ोल्डर किनारे कर देता है (वह बना रहता है, कुछ मिटाया नहीं जाता), खाली डेटा फ़ोल्डर के साथ कंटेनर शुरू करता है और डंप आयात करता है। इस डेटाबेस का उपयोग करने वाले अनुप्रयोग उसकी वही स्थिति देखेंगे जो डंप के समय थी।",
  "dbdump.importConfirmNoVersion": "यह {engine} डंप {container} में आयात करें? BombVault कंटेनर रोकता है, उसका डेटा फ़ोल्डर किनारे कर देता है (वह बना रहता है, कुछ मिटाया नहीं जाता), खाली डेटा फ़ोल्डर के साथ कंटेनर शुरू करता है और डंप आयात करता है। इस डेटाबेस का उपयोग करने वाले अनुप्रयोग उसकी वही स्थिति देखेंगे जो डंप के समय थी।",
  "dbdump.importNoVersion": "यह डंप अपने डेटाबेस का संस्करण दर्ज नहीं करता। यदि सर्वर इसे पढ़ न सका तो आयात विफल होगा।",
  "dbdump.importStops": "one=आयात के दौरान BombVault {apps} को भी रोकता है और बाद में उसे फिर से शुरू करता है। अगर आयात शुरू होने के बाद विफल हो, तो पुराना डेटा किनारे पड़ा रहता है और ऐप रुका रहता है।|other=आयात के दौरान BombVault इन ऐप्स को भी रोकता है: {apps}। बाद में वह उन्हें फिर से शुरू करता है। अगर आयात शुरू होने के बाद विफल हो, तो पुराना डेटा किनारे पड़ा रहता है और ऐप्स रुके रहते हैं।",
  "dbdump.importDone": "डेटाबेस आयात हो गया।",
  "dbdump.importRefused.busy": "कोई दूसरा बैकअप या पुनर्स्थापन चल रहा है। उसके पूरा होने पर फिर कोशिश करें।",
  "dbdump.importRefused.notRunning": "पहले कंटेनर शुरू करें; आयात को चलता हुआ सर्वर चाहिए।",
  "dbdump.importRefused.engineMismatch": "यह डंप उस प्रकार के डेटाबेस का नहीं है जो यह कंटेनर चलाता है।",
  "dbdump.importRefused.noDataMount": "BombVault इस कंटेनर के डेटा फ़ोल्डर तक नहीं पहुँच पाता, इसलिए उसे सुरक्षित ढंग से किनारे नहीं कर सकता। डंप को हाथ से आयात करें, जैसा पुनर्प्राप्ति किट बताती है।",
  "dbdump.importRefused.version": "सर्वर संस्करण {server} चला रहा है, डंप {dump} से आया है। इस आयात के लिए {dump} या उससे नया संस्करण वाली इमेज लें।",
  "dbdump.importRefused.versionSameMajor": "सर्वर संस्करण {server} चला रहा है, डंप {dump} से आया है। MySQL और MariaDB डंप को केवल उसी मुख्य संस्करण में आयात करते हैं जिससे वह आया है, इसलिए इस आयात के लिए संस्करण {dump} वाली इमेज लें।",
  "dbdump.importRefused.damaged": "यह डंप क्षतिग्रस्त है और आयात नहीं किया जा सकता।",
  "dbdump.importRefused.notADump": "यह स्नैपशॉट इस कंटेनर का डेटाबेस डंप नहीं है।",
  "dbdump.restoreLiveWarn": "इस डेटाबेस की फ़ाइलें सर्वर चलते हुए कॉपी होती हैं, इसलिए पुनर्स्थापित फ़ाइलें ठीक से शुरू न हों, यह हो सकता है। ऐसा हो तो इसी बैकअप के साथ लिया गया डंप आयात करें, जो नीचे सूची में है।",
  "dbdump.restoreNoneWarn": "इस डेटाबेस का डेटा फ़ोल्डर बैकअप में नहीं है। पुनर्स्थापन कंटेनर को खाली डेटाबेस के साथ लौटाता है; उसके बाद नीचे की सूची से कोई डंप आयात करें।",
  "dbdump.deleteConfirm": "यह डेटाबेस डंप मिटाएँ? यह रिपॉज़िटरी से हटा दिया जाएगा (जगह वापस पाने के लिए सेटिंग्स में Prune चलाएँ)। इसे पलटा नहीं जा सकता।",
