  "flash.zipExport.path": "एक्सपोर्ट फ़ोल्डर",
  "flash.zipExport.pathHint": "होस्ट माउंट रूट के अंतर्गत सापेक्ष उपपथ जहाँ .zip जाता है। फ़्लैश को स्वचालित रूप से सर्वर से बाहर लाने के लिए इसे किसी Syncthing/rclone फ़ोल्डर पर सेट करें।",
  "flash.zipExport.keepHistory": "एक्सपोर्ट की गई zip फ़ाइलें रखें",
  "flash.zipExport.keepHistoryHint": "बंद: एक ही flash-latest.zip रखा जाता है जो हर बार ओवरराइट होता है। चालू: टाइमस्टैंप वाली सबसे नई N flash-<date>.zip फ़ाइलें रखी जाती हैं। यह restic रिटेंशन से अलग है: बंद पर एक ही, हमेशा ओवरराइट होने वाली फ़ाइल रखी जाती है (गंतव्य कभी नहीं भरता); चालू पर सबसे नई N रखी जाती हैं और पुरानी हटा दी जाती हैं।",
  "flash.zipExport.keepN": "रखने योग्य zips",
  "flash.zipExport.keepNHint": "टाइमस्टैंप वाली सबसे नई N zips रखी जाती हैं; पुरानी स्वचालित रूप से हटा दी जाती हैं।",
  "flash.zipExport.latestNote": "एक flash-latest.zip हर बैकअप के बाद ओवरराइट होता है।",
  "flash.zipExport.plaintextWarn": "एक्सपोर्ट किया गया .zip एन्क्रिप्टेड नहीं है, भले ही आपकी फ़्लैश रिपॉज़िटरी हो। इसे केवल किसी भरोसेमंद जगह पर ही सिंक करें।",
  "flash.zipExport.pathRequired": "इसे चालू करने के लिए एक एक्सपोर्ट फ़ोल्डर चुनें।",
  "export.encrypt.hint": "restic रिपॉज़िटरीज़ पहले से ही एन्क्रिप्टेड हैं। यह वैकल्पिक रूप से सादे एक्सपोर्ट आर्टिफ़ैक्ट्स (कंटेनर और VM का tar.gz उनकी xml सहायक फ़ाइलों समेत, और फ़्लैश ज़िप) को age से बंद कर देता है, ताकि इन्हें बॉक्स से बाहर रखना या ले जाना सुरक्षित हो।",
  "export.encrypt.ageInfo": "age (age-encryption.org) एक छोटा, आधुनिक फ़ाइल-एन्क्रिप्शन टूल है: किसी फ़ाइल को एक या अधिक प्राप्तकर्ताओं के लिए सील करने के लिए GPG का एक सरल विकल्प।",
  "export.encrypt.enable": "एक्सपोर्ट को age से एन्क्रिप्ट करें",
  "export.encrypt.enableHint": "चालू होने पर, कंटेनर, VM और फ़्लैश के एक्सपोर्ट डिस्क पर लिखे जाने से पहले age से सील किए जाते हैं और उन्हें .age सफ़िक्स मिलता है।",
  "export.encrypt.kitSealed": "रिकवरी किट भी सील की जाती है और bombvault-recovery-kit.md.age के रूप में मिलती है। यह पढ़ने योग्य टेक्स्ट ही रहती है (ASCII armor), इसलिए इसे अब भी किसी पासवर्ड मैनेजर में चिपकाया या प्रिंट किया जा सकता है, लेकिन इसे खोलने के लिए आपकी age प्राइवेट की चाहिए: उस की को ऐसी जगह रखें जो खुद किट पर निर्भर न हो।",
  "export.encrypt.recipients": "age प्राप्तकर्ता",
  "export.encrypt.recipientsHint": "प्रति पंक्ति एक प्राप्तकर्ता। कोई age पब्लिक की (age1...) या SSH पब्लिक की उपयोग करें। बॉक्स के बाहर डिक्रिप्ट करने के लिए मिलती-जुलती प्राइवेट की चाहिए। एन्क्रिप्शन चालू होने और कोई मान्य प्राप्तकर्ता न होने पर, एक्सपोर्ट प्लेनटेक्स्ट लिखने के बजाय विफल हो जाता है।",
  "export.encrypt.recipientsPlaceholder": "age1qz...\nssh-ed25519 AAAA...",
  "export.encrypt.recipientsRequired": "कम से कम एक age प्राप्तकर्ता जोड़ें, नहीं तो एन्क्रिप्टेड एक्सपोर्ट विफल हो जाएगा।",

