  "pairing.relayCheckOwn": "क्या आपका रिले चल रहा है, और क्या उसका पता रिले कार्ड में सही है?",
  "pairing.relayCheckFilter": "क्या कोई फ़ायरवॉल या DNS फ़िल्टर उस पते को रोक रहा है?",
  "pairing.relayCheckTip": "एक ही नेटवर्क पर आपके इंस्टेंस को रिले की ज़रूरत नहीं होती, वे मल्टीकास्ट से एक-दूसरे को खोज लेते हैं। यह तब काम नहीं करता जब कंटेनर Docker के डिफ़ॉल्ट ब्रिज नेटवर्क में चलता है।",
  "pairing.checkAgain": "फिर से जाँचें",
  "relay.title": "रिले",
  "relay.hint": "एक ही नेटवर्क पर आपके इंस्टेंस सीधे एक-दूसरे से बात करते हैं। अलग-अलग नेटवर्क पर मौजूद इंस्टेंस के लिए, एक रिले संदेश आगे पहुँचाता है।",
  "relay.lead": "रिले BombVault इंस्टेंस को अलग-अलग नेटवर्क के पार भी जोड़ता है।",
  "relay.howItWorks": "यह कैसे काम करता है?",
  "relay.project": "प्रोजेक्ट रिले",
  "relay.own": "अपना रिले",
  "relay.off": "कोई रिले नहीं",
  "relay.projectSentence": "प्रोजेक्ट {host} पर रिले मुफ़्त में चलाता है।",
  "relay.projectNeed": "कुछ नहीं। यह बिना सेटअप के काम करता है।",
  "relay.projectSees": "कोई संदेश किस इंस्टेंस के लिए है, वह कितना बड़ा है, और कब पहुँचता है।",
  "relay.projectAlt": "आपके नेटवर्क में इंस्टेंस A और दूसरे नेटवर्क में इंस्टेंस B, प्रोजेक्ट रिले के ज़रिए जुड़े हुए। कुंजियाँ केवल A और B पर हैं।",
  "relay.ownSentence": "अपना ख़ुद का रिले चलाना चाहते हैं? इसके लिए आपके पास दो तरीक़े हैं। फिर रिले आपकी मशीन पर चलता है, और आपके इंस्टेंस आपके रिले के पते से जुड़ते हैं।",
  "relay.ownSees": "कोई संदेश किस इंस्टेंस के लिए है, वह कितना बड़ा है, और कब पहुँचता है। इसे आप चलाते हैं।",
  "relay.ownAlt": "इंस्टेंस A और इंस्टेंस B, आपके अपने रिले के ज़रिए जुड़े हुए। कुंजियाँ केवल A और B पर हैं।",
  "relay.offSentence": "आपके इंस्टेंस एक-दूसरे को केवल एक ही नेटवर्क पर पाते हैं। बाहर से आप इनमें से किसी तक नहीं पहुँच सकते।",
  "relay.offNeed": "सभी इंस्टेंस एक ही नेटवर्क पर।",
  "relay.offSees": "कोई नहीं। आपके नेटवर्क से कुछ भी बाहर नहीं जाता।",
  "relay.offAlt": "एक ही नेटवर्क पर इंस्टेंस A और B सीधे बात करते हैं। दूसरे नेटवर्क पर मौजूद इंस्टेंस C तक नहीं पहुँचा जा सकता।",
  "relay.needLabel": "आपको चाहिए:",
  "relay.howDoesTitle": "क्या होता है",
