  "relay.containerCert": "अपने डोमेन के साथ यह ख़ुद अपना सर्टिफ़िकेट ले आता है।",
  "relay.instanceName": "BombVault इंस्टेंस",
  "relay.instanceSub": "कोई भी जुड़ा हुआ इंस्टेंस रिले के रूप में काम कर सकता है, बशर्ते वह बाहर से पहुँच योग्य हो।",
  "relay.serve": "रिले के रूप में काम करें",
  "relay.serveHint": "इसे उस इंस्टेंस पर चालू करें जो बाहर से पहुँच योग्य है। यह फिर आपके समूह के दूसरे इंस्टेंस को /relay/connect पर, अपने ही पते पर जवाब देता है।",
  "relay.serveClients": "{n} इंस्टेंस अभी जुड़े हुए हैं",
  "relay.instanceCert": "फिर रिले उसी पते पर /relay/connect पर उसी रिवर्स प्रॉक्सी और सर्टिफ़िकेट के पीछे चलता है।",
  "relay.instanceCertTip": "इसे अपने सर्टिफ़िकेट की ज़रूरत नहीं है। जो भी आपके इंस्टेंस को बाहर से पहुँच योग्य बनाता है वह रिले के लिए भी काफ़ी है।",
  "relay.addressAfter": "बाद में पता, उदाहरण के लिए",
  "relay.addressLabel": "आपके रिले का पता",
  "relay.addressTip": "यह पता केवल इस इंस्टेंस पर लागू होता है। इसे हर उस इंस्टेंस पर दर्ज करें जिसे आपके रिले के ज़रिए पहुँच योग्य होना चाहिए।",
  "relay.plaintextWarning": "इस पते पर TLS नहीं है, इसलिए रिले की कुंजी नेटवर्क पर सादे पाठ में जाती है। रास्ते में कोई भी उसे पढ़कर रिले पर आपके समूह में शामिल हो सकता है। वह यह नहीं पढ़ सकता कि आपके इंस्टेंस एक-दूसरे को क्या भेजते हैं, पर देख सकता है कि कौन-से इंस्टेंस कब आपस में बात करते हैं। इसे केवल ऐसे नेटवर्क पर इस्तेमाल करें जिस पर आपको भरोसा हो।",
  "relay.diagramRelay": "रिले",
  "relay.diagramOwnAddress": "आपका पता",
  "relay.diagramYourNetwork": "आपका नेटवर्क",
  "relay.diagramOtherNetwork": "दूसरा नेटवर्क",
  "relay.diagramYourLan": "आपका नेटवर्क",
  "relay.legendKey": "कुंजी, केवल आपके इंस्टेंस पर",
  "relay.legendMessage": "संदेश, रास्ते में एन्क्रिप्टेड",
  "relay.e2e": "हर रास्ते पर सब कुछ एंड-टू-एंड एन्क्रिप्टेड है। चाहे रिले प्रोजेक्ट चलाए या आप, इनमें से कुछ भी पढ़ा नहीं जा सकता।",
  "relay.e2eTip": "कुंजी बारह शब्दों से बनती है और आपके इंस्टेंस पर रहती है। रिले सिर्फ़ यह देखता है कि कोई संदेश किस इंस्टेंस के लिए है, वह कितना बड़ा है और कब पहुँचता है। इसे एन्क्रिप्ट करके नहीं छुपाया जा सकता। अगर यह आपको खलता है, तो अपना रिले चलाएँ।",
  "relay.notSeesContent": "जो आपके इंस्टेंस आपस में भेजते हैं। यह एंड-टू-एंड एन्क्रिप्टेड है।",
  "relay.notSeesBackups": "आपके बैकअप। रिले से सिर्फ़ स्थिति, कमांड और पेयरिंग गुज़रते हैं।",
