  "fleet.openPairing": "पेयरिंग खोलें",
  "fleet.pairAgainTip": "इस पीयर को फ़्लीट टोकन से जोड़ा गया था। इस पर समूह का वाक्यांश दर्ज करें, और यह उसी नाम से दिखते ही इस पंक्ति को अपना लेगा।",
