  "pull.empty": "अभी तक कोई पुल स्रोत नहीं है। अपने पेयरिंग समूह से एक इंस्टेंस और उसकी रिपॉज़िटरी चुनें, और यह बॉक्स आपके चुने शेड्यूल पर इसके स्नैपशॉट अपनी ही रिपॉज़िटरी में लाता रहेगा। दूसरी तरफ़ को जागते रहने की ज़रूरत भी नहीं है।",
