  "zfs.safety.old": "सबसे पुराना सुरक्षा स्नैपशॉट 30 दिन से अधिक पुराना है। जब तक आप इसे हटाते नहीं, यह हटाया और बदला गया डेटा पूल पर रोके रखता है।",
  "zfs.safety.hint": "BombVault ने ये स्नैपशॉट किसी डेटासेट में रीस्टोर करने से ठीक पहले लिए, ताकि रीस्टोर से पहले की स्थिति वापस पाई जा सके। BombVault इन्हें कभी अपने आप नहीं हटाता। अलग-अलग फ़ाइलें वापस पाने के लिए उन्हें डेटासेट के भीतर .zfs/snapshot/<name> से कॉपी करें। zfs rollback केवल तब तक काम करता है जब तक यह उस डेटासेट का सबसे नया स्नैपशॉट है; zfs rollback -r हर नए स्नैपशॉट को हटा देता है, स्वचालित स्नैपशॉट को भी।",
  "zfs.safety.deleteConfirm": "{dataset} का सुरक्षा स्नैपशॉट {name} हटाएँ? उस रीस्टोर से पहले की स्थिति इसके बाद वापस नहीं पाई जा सकती।",
  "zfs.deleteRowConfirm": "इस आइटम को सूची से हटाएँ? इसके बैकअप रखे जाते हैं और बाद में फिर से खोजे जा सकते हैं।",
  "zfs.deleteSafetyToo": "सर्वर पर इसके सुरक्षा स्नैपशॉट भी हटाएँ",
  "zfs.deleteBackupsConfirm": "इस आइटम और इसके डेटासेट के सभी बैकअप हटाएँ? स्नैपशॉट स्थायी रूप से हटा दिए जाते हैं, रिपॉज़िटरी प्रून की जाती है और आइटम सूची से हटा दिया जाता है। इसे पूर्ववत नहीं किया जा सकता।",
