  "mcp.title": "MCP सर्वर",
  "mcp.hint": "Claude जैसे एआई सहायकों को Model Context Protocol के ज़रिए इस सर्वर के बैकअप की स्थिति पढ़ने, बैकअप शुरू करने और अपने शुरू किए बैकअप रद्द करने देता है। पुनर्स्थापना, विलोपन और सेटिंग्स इसी वेब इंटरफ़ेस में रहती हैं।",
  "mcp.statusOff": "बंद: कोई कुंजी नहीं है",
  "mcp.statusOn": "one=चालू, {n} सक्रिय कुंजी|other=चालू, {n} सक्रिय कुंजियाँ",
  "mcp.statusNoneWorks": "बंद: कोई भी कुंजी काम नहीं करती",
  "mcp.noPasswordWarning": "कोई लॉगिन पासवर्ड तय नहीं है, इसलिए यह वेब इंटरफ़ेस तुम्हारे नेटवर्क में सबके लिए खुला है, और जो इसे खोल सकता है वह कुंजी भी बना सकता है।",
  "mcp.setPassword": "लॉगिन पासवर्ड तय करो",
  "mcp.needsPasswordForHost": "यह पन्ना {host} के नाम से खुला है। लॉगिन पासवर्ड के बिना कुंजियाँ केवल किसी IP पते या tower या tower.local जैसे स्थानीय नाम से ही बनाई और बदली जा सकती हैं, ताकि इंटरनेट का कोई पन्ना कुंजी न बना सके। लॉगिन पासवर्ड इस पते के लिए यह रोक हटा देता है। तुम BombVault को उसके स्थानीय पते से भी खोल सकते हो।",
  "mcp.restoreRevokedNotice": "कॉन्फ़िगरेशन की पुनर्स्थापना ने हर MCP कुंजी रद्द कर दी। अपने सहायकों के लिए नई कुंजियाँ बनाओ।",
  "mcp.appKeyChanged": "इन कुंजियों के बनने के बाद APP_KEY बदल गया है, इसलिए वे अब काम नहीं करतीं। हर कुंजी बदलो और अपने सहायकों में नई कुंजी डालो।",
  "mcp.keyUnusable": "APP_KEY बदलने के बाद अब वैध नहीं",
