  "mcp.endpointLabel": "एंडपॉइंट",
  "mcp.endpointHint": "वह पता जिससे तुम्हारा असिस्टेंट जुड़ता है। यह Streamable HTTP बोलता है और Authorization या X-API-Key हेडर में कुंजी की उम्मीद करता है, या असिस्टेंट के OAuth से साइन-इन करने के बाद एक्सेस टोकन की।",
  "mcp.newKey": "नई कुंजी",
  "mcp.labelLabel": "कुंजी का नाम",
  "mcp.labelPlaceholder": "लैपटॉप पर Claude Code",
  "mcp.allowStart": "बैकअप शुरू करने दो",
  "mcp.allowStartHint": "यह चालू हो तो सहायक एक वस्तु, पूरे क्षेत्र या Backup Everything का बैकअप शुरू कर सकता है और अपने शुरू किए बैकअप रद्द कर सकता है: प्रति घंटे अधिकतम {n}, एक ही वस्तु के लिए {minutes} मिनट के अंतर से और प्रति वस्तु प्रतिदिन {perDay}। बैकअप चल रहे कंटेनरों को तब तक रोक देता है जब तक वह पूरा न हो। बंद होने पर कुंजी सिर्फ़ पढ़ सकती है।",
  "mcp.createKey": "कुंजी बनाओ",
