  "mcp.labelInvalid": "कुंजी को अधिकतम 64 अक्षरों का नाम दो।",
  "mcp.labelTaken": "एक सक्रिय कुंजी का नाम पहले से यही है।",
  "mcp.limitReached": "one=पहले से {n} सक्रिय कुंजी है। नई बनाने से पहले उसे रद्द करो।|other=पहले से {n} सक्रिय कुंजियाँ हैं। नई बनाने से पहले एक रद्द करो।",
  "mcp.newKeyTitle": "तुम्हारी नई कुंजी",
  "mcp.showOnce": "इसे अभी कॉपी कर लो। BombVault इसका सिर्फ़ फ़िंगरप्रिंट रखता है और इसे दोबारा नहीं दिखा सकता।",
  "mcp.copyKey": "कुंजी कॉपी करो",
  "mcp.dismissKey": "मैंने इसे कॉपी कर लिया",
  "mcp.snippetsLabel": "क्लाइंट जोड़ो",
  "mcp.connectHint": "अपना क्लाइंट चुनो और उसी के लिए बना सेटअप पाओ: उसके नाम वाली कुंजी, कॉपी करने के लिए कॉन्फ़िगरेशन और वह प्रमाणपत्र वाला चरण जिसकी उसे ज़रूरत है। कोई भी दूसरा क्लाइंट दूसरा क्लाइंट के ज़रिए जुड़ता है। सहायक जो पढ़ता है, जैसे आइटम के नाम, इतिहास और त्रुटि संदेश, वह उसके पीछे के AI प्रदाता तक जाता है, जब BombVault होस्ट पाथ, रिपॉज़िटरी की जगहें और क्रेडेंशियल हटा देता है।",
  "mcp.groupLocal": "इस कंप्यूटर पर",
  "mcp.groupCloud": "क्लाउड में",
  "mcp.cloudWarningTitle": "BombVault इंटरनेट से पहुँचने लायक होना चाहिए",
  "mcp.cloudWarning": "ये सेवाएँ BombVault को तुम्हारे कंप्यूटर से नहीं, अपने प्रदाता के सर्वरों से बुलाती हैं। तब BombVault सार्वजनिक रूप से भरोसेमंद प्रमाणपत्र के साथ इंटरनेट से पहुँचने लायक होना चाहिए, जैसे किसी रिवर्स प्रॉक्सी के पीछे। उस प्रॉक्सी का लॉगिन वेब इंटरफ़ेस की रक्षा कर सकता है, पर /mcp को BombVault तक जाने देना होगा, जो कुंजी खुद जाँचता है: ये सेवाएँ किसी प्रॉक्सी में लॉग इन नहीं कर सकतीं। Le Chat स्व-हस्ताक्षरित प्रमाणपत्र ठुकरा देता है।",
  "mcp.otherClient": "दूसरा क्लाइंट",
