  "mcp.pickHint": "BombVault ने हर कुंजी एक ही बार दिखाई थी, जब वह बनी। अगर वह अब तुम्हारे पास नहीं है, तो नई बनाओ।",
  "mcp.pickShared": "इस कुंजी से अगली कॉल पर चरण 3 हरा हो जाता है, चाहे वह कॉल कोई भी क्लाइंट करे। पक्का करने के लिए कि वह यही क्लाइंट था, हर क्लाइंट को उसकी अपनी कुंजी दो, जैसा नई कुंजी करता है।",
  "mcp.stepConfig": "BombVault को {name} में जोड़ो",
