  "mcp.stepOAuth": "साइन-इन चालू करो",
  "mcp.setupChatGPT": "ChatGPT में सेटिंग्स, ऐप्स और कनेक्टर खोलो और एडवांस्ड सेटिंग्स में डेवलपर मोड चालू करो। फिर बनाएँ चुनो, कनेक्टर को नाम दो, कनेक्टर URL को MCP सर्वर URL के रूप में पेस्ट करो, प्रमाणीकरण के लिए OAuth चुनो, पुष्टि करो कि तुम उस पर भरोसा करते हो और उसे बनाओ।",
  "mcp.setupClaudeAi": "claude.ai पर सेटिंग्स, कनेक्टर खोलो और कस्टम कनेक्टर जोड़ें चुनो। उसे नाम दो, कनेक्टर URL पेस्ट करो, OAuth क्लाइंट ID और सीक्रेट खाली छोड़ दो और उसे जोड़ो। फिर कनेक्ट करें चुनो।",
