  "mcp.oauthSignedIn": "{name} ने {time} पर साइन-इन किया। उसकी टाइल नीचे कार्ड पर है।",
  "mcp.notePerplexity": "अभी तक सिर्फ़ Perplexity का Mac ऐप तुम्हारे कंप्यूटर या नेटवर्क के MCP सर्वरों से जुड़ता है; Windows ऐप और वेबसाइट नहीं।",
  "mcp.noteGrok": "Grok के दस्तावेज़ उसका कनेक्टर फ़ॉर्म विस्तार से नहीं दिखाते। अगर वह सिर्फ़ साइन-इन देता है और हेडर के लिए कोई फ़ील्ड नहीं, तो वह अभी BombVault कुंजी इस्तेमाल नहीं कर सकता।",
  "mcp.certNotForThisAddress": "BombVault का प्रमाणपत्र {host} का नाम नहीं लेता, इसलिए सहायक इस पते से जुड़ने से मना कर देंगे। पता प्रमाणपत्र में जोड़ो और फिर उसे अंशों के लिए डाउनलोड करो।",
