  "files.repoHint": "इस सेट के बैकअप कहाँ रखे जाते हैं। खाली का अर्थ है फ़ोल्डर रिपॉज़िटरी। सूची में वे रिपॉज़िटरी हैं जो आपने सेटिंग्स में बनाईं, इसलिए स्थान एक बार लिखा जाता है और यहाँ केवल चुना जाता है।",
  "files.repoLocked": "सेट के बैकअप बन जाने के बाद यह नहीं बदला जा सकता: वे उसी रिपॉज़िटरी में रहते हैं जहाँ लिखे गए थे और कोई उन्हें नहीं ले जाता। पहले इस सेट के बैकअप हटाएँ, या नया सेट बनाएँ।",
  "files.nameLocked": "सेट के बैकअप बन जाने के बाद नाम नहीं बदला जा सकता, क्योंकि बैकअप इसी नाम के तहत रखे जाते हैं। नए नाम के लिए नया सेट बनाएँ।",
  "repos.title": "रिपॉज़िटरी",
  "repos.intro": "वे जगहें जहाँ बैकअप लिखे जा सकते हैं। यहाँ एक बनाएँ और फिर उसे किसी एक कंटेनर, वर्चुअल मशीन या फ़ोल्डर सेट पर चुनें, डोमेन की अपनी रिपॉज़िटरी के बजाय।",
  "repos.itemLabel": "रिपॉज़िटरी",
  "repos.itemDefault": "डोमेन की रिपॉज़िटरी",
  "repos.itemHint": "इस प्रविष्टि के बैकअप कहाँ जाते हैं। इसे डोमेन की रिपॉज़िटरी पर ही रहने दें, जब तक इसे अपनी अलग न चाहिए; आम वजह एक बड़ी, कम बदलने वाली प्रविष्टि होती है जिससे केवल ऑफ़-साइट प्रति चाहिए। सूची में वही है जो आपने सेटिंग्स में बनाया।",
  "repos.itemLocked": "प्रविष्टि के बैकअप बन जाने के बाद यह नहीं बदला जा सकता: वे उसी रिपॉज़िटरी में रहते हैं जहाँ लिखे गए थे और कुछ भी उन्हें नहीं हटाता। पहले उसके बैकअप मिटाएँ।",
  "repos.name": "नाम",
