  "repos.locationPlaceholder": "backups/cold या b2:bucket/path",
  "repos.locationHint": "होस्ट माउंट के नीचे एक फ़ोल्डर, या b2:bucket/path, s3:..., sftp:..., rest:... या rclone:... जैसी दूरस्थ restic रिपॉज़िटरी। दूरस्थ पर सीधे लिखा जाता है, बीच में कोई स्थानीय प्रति नहीं।",
  "repos.locationLocked": "जब तक कुछ यहाँ बैकअप ले रहा है, स्थान नहीं बदला जा सकता: अब तक लिखा सब कुछ वहीं रहता है, इसलिए अगला बैकअप एक खाली रिपॉज़िटरी में सफल हो जाता। दूसरी जोड़ें और प्रविष्टियाँ उस पर लगाएँ।",
