  "anomaly.cardHint": "BombVault किसी आइटम के हर बैकअप की तुलना पिछले बैकअप से करता है और बताता है कि क्या मेल नहीं खाता: सामान्य से बहुत अधिक नया डेटा, अधिकांश डेटा का दोबारा लिखा जाना, तेज़ी से सिकुड़ा या बढ़ा हुआ स्रोत, छोटा हो गया डेटाबेस डंप, अचानक बहुत अधिक समय लेने वाला बैकअप, बार-बार विफलता, वह पुनर्स्थापना जाँच जो अब पास नहीं होती, और जल्द भर जाने वाली डिस्क। अधिकांश जाँचों के लिए पहले किसी आइटम के 10 बैकअप चाहिए। ZFS आइटम की जाँच डेटासेट दर डेटासेट होती है, इसलिए खाली किया गया चाइल्ड डेटासेट बड़े ट्री में भी दिख जाता है।",
