  "anomaly.acknowledgeHint": "इस विसंगति को देखा हुआ चिह्नित करता है और बंद कर देता है। जब तक कारण बना रहेगा, दोबारा सूचित नहीं किया जाएगा; कारण समाप्त होकर लौटे तो सूचित किया जाएगा। यदि यह विसंगति पुराने बैकअप रोके हुए है, तो अगली सफ़ाई से वे फिर हटाए जाएँगे। यदि बदलाव जानबूझकर किया गया था, तो उसे अपेक्षित चिह्नित करना बेहतर है।",
  "anomaly.expectedHint": "BombVault को बताता है कि बदलाव जानबूझकर किया गया था। नया आकार या नई अवधि 10 और बैकअप के बाद सामान्य स्तर बन जाती है, जबकि लगभग खाली स्रोत की जाँच चालू रहती है। नए डेटा के लिए इस मात्रा तक की मात्राएँ इस आइटम के लिए अब सूचित नहीं की जाएँगी। यदि यह विसंगति पुराने बैकअप रोके हुए है, तो अगली सफ़ाई से वे फिर हटाए जाएँगे।",
