  "anomaly.sentence.newData": "{name} ने एक ही बैकअप में {bytes} नया डेटा जोड़ा। सामान्यतः अधिकतम {typical} जुड़ता है।",
  "anomaly.sentence.newDataRewrite": "{name} ने एक ही बैकअप में {bytes} दोबारा लिखा, यानी जो कुछ सहेजा जाता है उसका कम से कम आधा ({source})। यदि आपने इतना नहीं बदला, तो जाँचें कि फ़ाइलें एन्क्रिप्ट या प्रतिस्थापित तो नहीं हुईं।",
  "anomaly.sentence.newDataRenamed": "{name} की सभी फ़ाइलें नई लगती हैं जबकि पुराना बैकअप मौजूद है, और {source} में से {bytes} दोबारा सहेजा गया। एक साथ नाम बदली और दोबारा लिखी गई फ़ाइलें रैनसमवेयर की पहचान हैं। सबसे पहले फ़ाइलें जाँचें।",
  "anomaly.sentence.newDataFull": "BombVault ने {name} की सभी फ़ाइलें दोबारा पढ़ीं, क्योंकि कोई पुराना बैकअप मेल नहीं खाया (नया रिपॉजिटरी, नए फ़ोल्डर या बदला हुआ एन्क्रिप्शन)। सहेजा गया नया डेटा: {bytes}।",
  "anomaly.sentence.sourceCollapse": "{name} लगभग खाली है: {current}, सामान्यतः {typical}। जाँचें कि डेटा हटाया गया है या कोई डिस्क माउंट नहीं है।",
  "anomaly.sentence.sourceDrain": "{name} ने पिछले हफ़्तों में अपना अधिकांश डेटा खो दिया: {current}, पहले {typical}।",
  "anomaly.sentence.sourceShrink": "{name} घटकर {current} रह गया, सामान्यतः {typical}।",
  "anomaly.sentence.sourceGrowth": "{name} बढ़कर {current} हो गया, सामान्यतः {typical}।",
  "anomaly.sentence.dumpCollapse": "{name} का डेटाबेस डंप लगभग खाली है: {current}, सामान्यतः {typical}। जाँचें कि डेटाबेस ने अपना डेटा तो नहीं खोया।",
  "anomaly.sentence.dumpShrink": "{name} का डेटाबेस डंप घटकर {current} रह गया, सामान्यतः {typical}।",
  "anomaly.sentence.dumpGrowth": "{name} का डेटाबेस डंप बढ़कर {current} हो गया, सामान्यतः {typical}।",
  "anomaly.sentence.dumpDuration": "{name} के डेटाबेस डंप में {current} लगा, सामान्यतः {typical}।",
  "anomaly.sentence.dumpFailureStreak": "{name} का डेटाबेस डंप बार-बार विफल हो रहा है। लगातार विफल डंप: {count}।",
  "anomaly.sentence.dumpFlaky": "{name} का डेटाबेस डंप कभी-कभी विफल होता है, हालाँकि पिछला सफल रहा। पिछले {total} में विफल: {failed}।",
  "anomaly.sentence.filesCollapse": "{name} में लगभग कोई फ़ाइल नहीं बची। फ़ाइलों की संख्या: {current}, सामान्यतः {typical}।",
  "anomaly.sentence.filesShrink": "{name} की फ़ाइल संख्या घटकर {current} रह गई, सामान्यतः {typical}।",
  "anomaly.sentence.duration": "{name} के बैकअप में {current} लगा, सामान्यतः {typical}।",
  "anomaly.sentence.failureStreak": "{name} बार-बार विफल हो रहा है। लगातार विफल बैकअप: {count}।",
  "anomaly.sentence.flaky": "{name} कभी-कभी विफल होता है, हालाँकि पिछला बैकअप सफल रहा। पिछले {total} में विफल: {failed}।",
  "anomaly.sentence.drill": "{domain} की पुनर्स्थापना जाँच ({source}) विफल रही, जबकि पहले पास होती थी।",
  "anomaly.sentence.drillTarget": "बाहरी गंतव्य {target} पर {domain} की पुनर्स्थापना जाँच विफल रही, जबकि पहले पास होती थी।",
  "anomaly.sentence.drillDr": "{domain} की बाहरी परीक्षण पुनर्स्थापना विफल रही, जबकि पहले पास होती थी।",
  "anomaly.sentence.drillDrTarget": "बाहरी गंतव्य {target} से {domain} की परीक्षण पुनर्स्थापना विफल रही, जबकि पहले पास होती थी।",
  "anomaly.sentence.capacityEta": "{domains} रखने वाली डिस्क इस रफ़्तार से लगभग {time} में भर जाएगी।",
