  "anomaly.sentence.unknown": "{name} के लिए एक विसंगति मिली। विवरण देखने के लिए पृष्ठ फिर से लोड करें।",
  "anomaly.offPage": "विसंगति पहचान बंद है। पहले की विसंगतियाँ यहाँ सूचीबद्ध रहती हैं।",
