  "anomaly.emptyOpen": "कोई खुली विसंगति नहीं।",
  "anomaly.emptyClosed": "इस अवधि में कोई बंद विसंगति नहीं।",
  "anomaly.items.hint": "हर बैकअप किया गया आइटम, उसकी सीखने की प्रगति, उसके सामान्य मान और उसकी अपनी संवेदनशीलता तथा सूचना सेटिंग के साथ। जब तक तुम यहाँ कुछ और नहीं चुनते, आइटम वैश्विक सेटिंग का पालन करता है। किसी कंटेनर के डेटाबेस डंप और किसी ZFS आइटम के हर डेटासेट की आइटम के नीचे अपनी अलग पंक्ति होती है।",
