  "anomaly.settings.hint": "किसी आइटम के हर बैकअप की तुलना उसके अपने इतिहास से करता है और जो मेल नहीं खाता उसकी रिपोर्ट करता है। यह हर बैकअप के बाद बैकग्राउंड में चलता है और किसी को धीमा नहीं करता। ज़्यादातर जाँचें किसी आइटम के 10 बैकअप के बाद शुरू होती हैं; विफलताएँ, ज़्यादातर डेटा का दोबारा लिखा जाना और लगभग खाली स्रोत शुरू से जाँचे जाते हैं। खाली जगह पर लोकल रिपॉज़िटरी और उन rclone रिपॉज़िटरी के लिए नज़र रखी जाती है जो इसे बताती हैं; Unraid यूज़र शेयर पर यह पूरे ऐरे की खाली जगह होती है।",
